const kindTips = { spelling: 'This word is misspelled.', homophone: 'These words sound alike but mean different things.', grammar: 'This is not the correct grammar.', agreement: 'The verb must agree with its subject.', apostrophe: 'The apostrophe is wrong or missing.', article: 'Choose a or an by the next sound.', preposition: 'The preposition is not the one English uses here.', tense: 'The verb form is wrong for this tense.', plural: 'This plural form is wrong.', wordchoice: 'These words are not used in this way.' };
function reasonFor(right, wrong, kind) {
  const r = splitToken(right).core.toLowerCase(), w = splitToken(wrong).core.toLowerCase();
  return pairTips[`${r}>${w}`] || (kind === 'spelling' && spellingTips[r]) || kindTips[kind];
}

// Common ESL errors, added in groups. Every wrong form below is wrong wherever the rules allow it to be chosen.
const add = (right, wrong, kind, reason, guard) => { (wrongForms[right] ||= []).unshift([wrong, kind, guard, reason]); };
const days = /^(monday|tuesday|wednesday|thursday|friday|saturday|sunday)$/;
