add('goes', 'go', 'agreement', 'With he, she, it or one person, the verb is "goes": she goes.');
add('go', 'goes', 'agreement', 'With I, you, we, they or a plural subject, the verb is "go": they go.', c => !plainVerb.has(c.prev));
